<script>
(function () {
  /* ── Find or create the copyright trigger element ── */
  function attachTrigger() {
    /* Try to locate an existing copyright element in the footer */
    var existing = Array.from(document.querySelectorAll('footer, .footer, #footer'))
      .reduce(function (found, el) {
        if (found) return found;
        var walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        var node;
        while ((node = walker.nextNode())) {
          if (node.textContent.includes('2026') && node.textContent.includes('DepEd')) {
            return node.parentElement;
          }
        }
        return null;
      }, null);

    if (!existing) {
      /* Fallback: inject our own copyright line at bottom of page */
      var bar = document.createElement('p');
      bar.style.cssText = 'text-align:center;font-size:.78rem;color:#aaa;padding:1rem 0 1.5rem;margin:0';
      bar.innerHTML = '&copy; 2026 DepEd LRMDS &ndash; Prototype. For demonstration purposes only.';
      document.body.appendChild(bar);
      existing = bar;
    }

    existing.id = 'easter-trigger';
    existing.setAttribute('data-clicks', '0');
    existing.title = '';

    var clicks = 0;
    existing.addEventListener('click', function () {
      clicks++;
      existing.setAttribute('data-clicks', clicks);
      if (clicks >= 7) {
        clicks = 0;
        existing.setAttribute('data-clicks', '0');
        document.getElementById('easter-overlay').classList.add('open');
        document.body.style.overflow = 'hidden';
      }
    });
  }

  /* ── Close handlers ── */
  function closeEgg() {
    document.getElementById('easter-overlay').classList.remove('open');
    document.body.style.overflow = '';
  }

  document.getElementById('easter-close').addEventListener('click', closeEgg);
  document.getElementById('easter-overlay').addEventListener('click', function (e) {
    if (e.target === this) closeEgg();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') closeEgg();
  });

  /* Run after DOM ready */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', attachTrigger);
  } else {
    attachTrigger();
  }
})();
</script>

